import assert from 'node:assert/strict';
import { performance } from 'node:perf_hooks';
import { uniqueTags } from '../src/tags.js';

const mode = process.argv[2];
if (mode === 'case') {
  const cases = [
    [['JS', 'Node', 'js', 'NODE', 'css'], ['JS', 'Node', 'css']],
    [['a', 'A', 'b', 'B', 'a', 'C', 'c'], ['a', 'b', 'C']],
    [['NODE', 'node', 'Node', 'nOdE'], ['NODE']],
    [['', '', 'X', 'x', ' x', ' X', 'x ', 'X ', 'x-y', 'X-Y', 'xy'], ['', 'X', ' x', 'x ', 'x-y', 'xy']],
    [['École', 'éCOLE', 'Über', 'ÜBER', 'Ω', 'ω'], ['École', 'Über', 'Ω']],
    [['__proto__', '__PROTO__', 'constructor', 'CONSTRUCTOR', 'toString', 'TOSTRING'], ['__proto__', 'constructor', 'toString']],
  ];
  for (const [input, expected] of cases) {
    const snapshot = input.slice();
    assert.deepEqual(uniqueTags(input), expected);
    assert.deepEqual(input, snapshot, 'must not change the input');
  }
  // A deterministic interleaving with many distinct keys checks both spelling and order.
  const input = [];
  const expected = [];
  const seen = new Set();
  for (let i = 0; i < 20000; i++) {
    const key = `tag-${(i * 97) % 1301}`;
    const tag = i % 3 === 0 ? key.toUpperCase() : key;
    input.push(tag);
    if (!seen.has(key)) { seen.add(key); expected.push(tag); }
  }
  assert.deepEqual(uniqueTags(input), expected);
} else if (mode === 'legacy') {
  for (const [input, expected] of [
    [[], []],
    [['node', 'js', 'node', 'css', 'js'], ['node', 'js', 'css']],
    [['z', 'b', 'a', 'z', 'b'], ['z', 'b', 'a']],
    [['', 'a', '', ' a', 'a ', 'a-b', 'ab'], ['', 'a', ' a', 'a ', 'a-b', 'ab']],
  ]) {
    const snapshot = input.slice();
    assert.deepEqual(uniqueTags(input), expected);
    assert.deepEqual(input, snapshot);
  }
} else if (mode === 'speed' || mode === 'benchmark') {
  const n = 120000;
  const distinct = Array.from({ length: n }, (_, i) => `Tag-${i}`);
  const input = [...distinct, ...distinct.map(x => x.toLowerCase()), ...distinct.map(x => x.toUpperCase())];
  uniqueTags(input.slice(0, 10000));
  const times = [];
  for (let trial = 0; trial < 3; trial++) {
    const start = performance.now();
    const result = uniqueTags(input);
    times.push(performance.now() - start);
    assert.ok(Array.isArray(result));
    assert.ok(result.length >= n && result.length <= input.length);
    assert.equal(result[0], distinct[0]);
  }
  times.sort((a, b) => a - b);
  const median = times[1];
  if (mode === 'speed') assert.ok(median < 750, `360000 tags took ${median.toFixed(1)} ms (limit 750 ms)`);
  console.log(median);
} else {
  throw new Error('expected case, legacy, speed, or benchmark');
}
